import{_ as t,o as n,c as r,a2 as s}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Wie füge ich mein erstes ESPHome-Gerät hinzu?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/03.erstes-geraet.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/erstes-geraet.md","filePath":"de/adapter/esphome/erste-schritte/erstes-geraet.md","lastUpdated":1795571670000}'),i={name:"de/adapter/esphome/erste-schritte/erstes-geraet.md"};function a(d,e,o,h,c,l){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="wie-fuge-ich-mein-erstes-esphome-gerat-hinzu" tabindex="-1">Wie füge ich mein erstes ESPHome-Gerät hinzu? <a class="header-anchor" href="#wie-fuge-ich-mein-erstes-esphome-gerat-hinzu" aria-label="Permalink to &quot;Wie füge ich mein erstes ESPHome-Gerät hinzu?&quot;">​</a></h1><p><a id="add-esphome-device-adapter"></a></p><h2 id="wie-fuge-ich-ein-esphome-gerat-im-adapter-hinzu" tabindex="-1">Wie füge ich ein ESPHome-Gerät im Adapter hinzu? <a class="header-anchor" href="#wie-fuge-ich-ein-esphome-gerat-im-adapter-hinzu" aria-label="Permalink to &quot;Wie füge ich ein ESPHome-Gerät im Adapter hinzu?&quot;">​</a></h2><p>Ein Gerät fügst du im Reiter „Geräte“ der Instanzeinstellungen hinzu. Die Instanz muss dafür laufen.</p><ol><li>Prüfe, dass in der YAML des Geräts <code>api:</code> steht, und kopiere den Schlüssel unter <code>api:</code> → <code>encryption:</code> → <code>key:</code>.</li><li>Öffne die Einstellungen der Instanz und dort den Reiter „Geräte“.</li><li>Klick auf „Gerät hinzufügen“.</li><li>Trag die IP-Adresse oder den Hostnamen des Geräts und den Verschlüsselungsschlüssel ein. „API-Passwort (veraltet)“ brauchst du nur bei Geräten ohne Schlüssel mit ESPHome vor 2026.1. Ist die API ungeschützt, lass beide Felder leer.</li><li>Bestätige. Der Adapter verbindet sich und zeigt nach höchstens 30 Sekunden das Ergebnis.</li></ol><p>Geklappt hat es bei „OK - Gerät erfolgreich verbunden, Konfiguration wird initialisiert“. Das Gerät steht dann in der Gruppe „Hinzugefügte Geräte“, seine Datenpunkte unter <code>esphome.0.&lt;Gerät&gt;</code>. Antwortet das Gerät nicht in 30 Sekunden, versucht der Adapter es im Hintergrund weiter.</p><p>Hat die Erkennung das Gerät schon gefunden, steht es in der Gruppe „Gefunden, noch nicht hinzugefügt“. Dort klickst du auf „Hinzufügen“, die Adresse ist schon eingetragen.</p><p><strong>Siehe auch:</strong> <a href="#encryption-key-not-accepted">Schlüssel wird nicht akzeptiert</a> · <a href="#no-datapoints-shown-object-tree">Keine Datenpunkte im Objektbaum</a> · <a href="./../anleitungen/geraete-entdecken#auto-discovery-report-routers-foreign">Geräte-Erkennung</a></p><p><a id="api-password-still-work-esphome"></a></p><h2 id="wo-trage-ich-das-api-passwort-ein-und-gilt-es-noch-mit-esphome-2026-1" tabindex="-1">Wo trage ich das API-Passwort ein und gilt es noch mit ESPHome 2026.1? <a class="header-anchor" href="#wo-trage-ich-das-api-passwort-ein-und-gilt-es-noch-mit-esphome-2026-1" aria-label="Permalink to &quot;Wo trage ich das API-Passwort ein und gilt es noch mit ESPHome 2026.1?&quot;">​</a></h2><p>Das API-Passwort trägst du im Dialog des Geräts im Feld „API-Passwort (veraltet)“ ein, beim Hinzufügen oder über „Verbindungseinstellungen ändern“. Gemeint ist das Passwort aus <code>api:</code> → <code>password:</code> der YAML, nicht das OTA-Passwort.</p><p>Ab ESPHome 2026.1 gibt es das API-Passwort nicht mehr, dann geht nur der Verschlüsselungsschlüssel. Steht ein Schlüssel im Dialog, nutzt der Adapter nur den Schlüssel und ignoriert das Passwort.</p><p>Lehnt das Gerät das Passwort ab, steht im Log <code>Device &lt;IP&gt; rejected the API password</code>, und <code>info._connectionStatus</code> des Geräts lautet <code>API password incorrect</code>.</p><p><strong>Siehe auch:</strong> <a href="#encryption-key-not-accepted">Schlüssel wird nicht akzeptiert</a></p><p><a id="encryption-key-not-accepted"></a></p><h2 id="warum-wird-mein-verschlusselungsschlussel-nicht-akzeptiert" tabindex="-1">Warum wird mein Verschlüsselungsschlüssel nicht akzeptiert? <a class="header-anchor" href="#warum-wird-mein-verschlusselungsschlussel-nicht-akzeptiert" aria-label="Permalink to &quot;Warum wird mein Verschlüsselungsschlüssel nicht akzeptiert?&quot;">​</a></h2><p>Den Schlüssel trägst du pro Gerät im Reiter „Geräte“ ein, beim Hinzufügen oder über „Verbindungseinstellungen ändern“. Er steht in der YAML unter <code>api:</code> → <code>encryption:</code> → <code>key:</code>. Kopiere ihn ohne Anführungszeichen.</p><p>Am Log erkennst du, was nicht passt:</p><table tabindex="0"><thead><tr><th>Im Log</th><th>Status des Geräts</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>Device &lt;IP&gt; requires an encryption key, …</code></td><td><code>Encryption Key Missing</code></td><td>Das Gerät verlangt einen Schlüssel, im Adapter fehlt er.</td></tr><tr><td><code>ESPHome client &lt;IP&gt; … Handshake failure</code></td><td>wechselt bei jedem Versuch</td><td>Der Schlüssel passt nicht zum Gerät.</td></tr></tbody></table><p>Passt der Schlüssel nicht, öffne beim Gerät „Verbindungseinstellungen ändern“ und trag den Schlüssel aus der aktuell geflashten YAML ein. Lässt du beide Felder leer, behält der Adapter die gespeicherten Zugangsdaten.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/log-meldungen#deserializebinary-assertion-failed-bad-format">Weitere Meldungen der Bibliothek</a> · <a href="./../anleitungen/geraete-verwalten#recover-stored-masked-api-password">Gespeicherten Schlüssel wiederfinden</a></p><p><a id="no-datapoints-shown-object-tree"></a></p><h2 id="warum-erscheinen-keine-datenpunkte-im-objektbaum-obwohl-das-gerat-lauft" tabindex="-1">Warum erscheinen keine Datenpunkte im Objektbaum, obwohl das Gerät läuft? <a class="header-anchor" href="#warum-erscheinen-keine-datenpunkte-im-objektbaum-obwohl-das-gerat-lauft" aria-label="Permalink to &quot;Warum erscheinen keine Datenpunkte im Objektbaum, obwohl das Gerät läuft?&quot;">​</a></h2><p>Datenpunkte legt der Adapter erst an, wenn das Gerät im Reiter „Geräte“ hinzugefügt ist und die Verbindung steht. Ein Gerät, das nur im Dashboard oder in der Gruppe „Gefunden, noch nicht hinzugefügt“ steht, hat keine Datenpunkte.</p><p>Geh so vor:</p><ol><li>Prüfe im Reiter „Geräte“, ob das Gerät unter „Hinzugefügte Geräte“ steht und verbunden ist. Wenn nicht, füg es hinzu.</li><li>Prüfe, ob die YAML die Entitäten enthält, die du erwartest, z. B. <code>sensor:</code> oder <code>switch:</code>. Nur was das Gerät über die API meldet, wird zum Datenpunkt.</li><li>Lade den Tab „Objekte“ neu.</li></ol><p>Die Datenpunkte liegen unter <code>esphome.0.&lt;Gerät&gt;.&lt;Typ&gt;.&lt;Schlüssel&gt;</code>. <code>&lt;Gerät&gt;</code> ist die MAC-Adresse ohne Doppelpunkte, nicht der Name aus der YAML. Den Namen siehst du in der Spalte „Name“.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/datenpunkte#datapoint-path-contain-number-instead">Aufbau der Datenpunkt-Pfade</a></p>',28)])])}const g=t(i,[["render",a]]);export{p as __pageData,g as default};
